import httpx

BASE_URL = "https://api.openweathermap.org/data/2.5/weather"


class WeatherAPIError(Exception):
    pass


def fetch_weather(city: str, api_key: str, units: str = "metric") -> dict:
    params = {
        "q": city,
        "appid": api_key,
        "units": units,
    }
    response = httpx.get(BASE_URL, params=params, timeout=10)

    if response.status_code == 401:
        raise WeatherAPIError("Invalid API key. Check your OPENWEATHER_API_KEY.")
    if response.status_code == 404:
        raise WeatherAPIError(f"City '{city}' not found.")
    if response.status_code != 200:
        raise WeatherAPIError(f"API error (HTTP {response.status_code}): {response.text}")

    return response.json()

